create table if not exists public.organization_college_ratings (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,college_id uuid not null references public.colleges(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,communication smallint check (communication between 1 and 5),recruiting_experience smallint check (recruiting_experience between 1 and 5),organization_relationship smallint check (organization_relationship between 1 and 5),follow_through smallint check (follow_through between 1 and 5),overall_experience smallint check (overall_experience between 1 and 5),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,college_id,user_id));
create table if not exists public.organization_college_notes (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,college_id uuid not null references public.colleges(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,visibility text not null default 'private' check (visibility in ('private','shared')),note text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.organization_college_ratings enable row level security;alter table public.organization_college_notes enable row level security;
create policy "org members read college ratings" on public.organization_college_ratings for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=organization_college_ratings.organization_id and m.user_id=auth.uid() and m.status='active'));
create policy "staff manage own college rating" on public.organization_college_ratings for all to authenticated using (user_id=auth.uid() and exists(select 1 from public.organization_members m where m.organization_id=organization_college_ratings.organization_id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin','advisor'))) with check (user_id=auth.uid() and exists(select 1 from public.organization_members m where m.organization_id=organization_college_ratings.organization_id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin','advisor')));
create policy "org members read shared or own college notes" on public.organization_college_notes for select to authenticated using ((visibility='shared' or user_id=auth.uid()) and exists(select 1 from public.organization_members m where m.organization_id=organization_college_notes.organization_id and m.user_id=auth.uid() and m.status='active'));
create policy "staff manage own college notes" on public.organization_college_notes for all to authenticated using (user_id=auth.uid() and exists(select 1 from public.organization_members m where m.organization_id=organization_college_notes.organization_id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin','advisor'))) with check (user_id=auth.uid() and exists(select 1 from public.organization_members m where m.organization_id=organization_college_notes.organization_id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin','advisor')));
create index organization_college_ratings_lookup on public.organization_college_ratings(organization_id,college_id);create index organization_college_notes_lookup on public.organization_college_notes(organization_id,college_id,visibility);